INSERT INTO ui_strings (key, locale, value) VALUES
 ('help.button', 'en', 'Help'),
 ('help.title', 'en', 'Help'),
 ('help.aboutpage', 'en', 'About this page'),
 ('help.atstage', 'en', 'At {stage}: your actions'),
 ('help.noactions', 'en', 'There is nothing for you to do on this task right now.'),
 ('help.ask.heading', 'en', 'Ask a question'),
 ('help.ask.placeholder', 'en', 'For example: why can''t I complete this invoice?'),
 ('help.ask.button', 'en', 'Ask'),
 ('help.ask.thinking', 'en', 'Thinking…'),
 ('help.ask.failed', 'en', 'Sorry, an answer could not be produced right now. Try again, or ask your AP manager.'),
 ('help.ask.disclaimer', 'en', 'Answers are generated by AI from this help and the facts of the task you have open. Check anything important with your AP manager.'),
 ('help.screen.dashboard', 'en', 'Your starting point. The cards summarise the work waiting for you and your team, invoices that need attention (unplaced, awaiting the ERP, possible duplicates), and how work is flowing through each stage. Click a card to open the matching list. Use Arrange to reorder or hide cards.'),
 ('help.screen.tasks', 'en', 'Every task you can see, across every stage. Available tasks belong to your team and are waiting to be claimed, Mine are yours to work, and Locked are claimed by someone else. Filter by stage or search, then click a row to open the invoice and its actions.'),
 ('help.screen.documents', 'en', 'Every invoice and document in the system, whether or not anyone is working on it. Search, filter by status, and open one to see the document, its facts, its timeline and chat. Documents opened here are read-only unless you have a task on them.'),
 ('help.screen.suppliers', 'en', 'Your supplier master, loaded from your ERP or recorded here. Click a supplier to hold, release, activate, deactivate or edit it. The ERP is the master, so the next load overwrites manual edits.'),
 ('help.screen.access', 'en', 'Who can do what, where. Org Units defines your companies and departments, Roles the permissions people hold, People each user and their properties (including approval limits), and Teams the groups tasks are assigned to.'),
 ('help.screen.sources', 'en', 'Where invoices arrive from: an email address, an upload, or UBL. Each source decides which process an invoice starts and which org it is placed in.'),
 ('help.screen.purchaseorders', 'en', 'Purchase orders loaded from your ERP or received as Peppol Orders. Invoices are matched against them line by line.'),
 ('help.screen.rules', 'en', 'The rules each stage runs, written in plain English and compiled into conditions and actions. A rule only runs once it has been confirmed and activated.'),
 ('help.screen.processes', 'en', 'The stages an invoice passes through, in order, and which rule set each stage runs. Changes are made as a draft and published as a new version, and invoices already in progress finish on the version they started.'),
 ('help.screen.apsetup', 'en', 'How invoices are matched, coded and approved: matching tolerances, Account Coding lists, which stages restrict coding, where tasks can be returned to, and the Approval Hierarchy mode with its definitions.'),
 ('help.screen.apanalytics', 'en', 'Reports on your AP operation: workload, supplier performance, financial performance, fraud prevention, the multi-entity CFO view, and Talk to an AP Expert.'),
 ('help.screen.viewer', 'en', 'One invoice, and the task you have on it. The document is on one side, its facts, lines and coding on the other, with the Timeline and Chat beneath. The buttons at the top are the actions open to you at this stage. Each is explained below, with the reason it is there.'),
 ('help.action.claim', 'en', 'Take this task from your team''s queue so that you can work on it. Nobody else can act on it while you hold it.'),
 ('help.action.complete', 'en', 'Finish your work at this stage. The invoice moves on to the next stage in the process.'),
 ('help.action.route_to_approver', 'en', 'Choose who should approve this invoice. Your choice gets the Approval task, and the invoice waits at Approval until they act.'),
 ('help.action.release', 'en', 'Put this task back in your team''s queue for someone else to claim.'),
 ('help.action.reassign', 'en', 'Hand this task directly to a named colleague in the same team.'),
 ('help.action.key', 'en', 'Edit the invoice''s header fields and lines, then Save. Only the fields this stage allows are editable.'),
 ('help.action.return', 'en', 'Send the invoice back to an earlier stage it has already been through, with a reason, for that stage''s team to correct.'),
 ('help.action.return_to_supplier', 'en', 'Send the invoice back to the supplier with a reason and an optional comment. It leaves the process, and the supplier is emailed.'),
 ('help.action.discard', 'en', 'Remove the invoice from the process, for example a duplicate or a document that is not an invoice. It is archived, not deleted.'),
 ('help.reason.task_closed', 'en', 'This task is already {status}.'),
 ('help.reason.claimed_by_other', 'en', '{name} has claimed this task, so only they can act on it. An AP manager can release or reassign it.'),
 ('help.reason.team_task_unclaimed', 'en', 'This task belongs to your team and nobody has claimed it yet. Claim it to see its other actions.'),
 ('help.reason.lacks_permission', 'en', 'You do not hold {permission} for this invoice''s org, so you can view it but not act on it.'),
 ('help.reason.limit_insufficient', 'en', 'Why Route To Approver and not Complete: your approval limit ({currency} {limit}) does not cover this invoice ({currency} {amount}), and Approval is set to Manual. Choose someone who can approve it.'),
 ('help.reason.choose_next_approver', 'en', 'Why Route To Approver and not Complete: the next stage, {stage}, uses the Approval Hierarchy and it is set to Manual, so you choose who approves this invoice.'),
 ('help.reason.limit_covers', 'en', 'Why Complete: your approval limit ({currency} {limit}) covers this invoice ({currency} {amount}), so you can approve it yourself.'),
 ('help.reason.complete_moves_on', 'en', 'Complete moves the invoice on to the next stage. Approval routing is set to {mode}, so nobody needs to be chosen here.'),
 ('help.reason.coding_incomplete', 'en', 'Account Coding is not finished on {lines} line(s). Every coding field this stage lets you edit must hold a valid value on every line before the invoice can move on.'),
 ('help.reason.return_targets', 'en', 'You can return this invoice to: {stages}.'),
 ('help.reason.return_no_targets', 'en', 'Return is not available here: no earlier stage this invoice has visited is set up as a return target for this stage (AP Setup).'),
 ('help.reason.discard_not_here', 'en', 'Discard is not allowed at {stage} (AP Setup, Stage Restrictions).');
INSERT INTO ui_strings (key, locale, value) VALUES
 ('help.button', 'de', 'Hilfe'),
 ('help.title', 'de', 'Hilfe'),
 ('help.aboutpage', 'de', 'Über diese Seite'),
 ('help.atstage', 'de', 'In {stage}: Ihre Aktionen'),
 ('help.noactions', 'de', 'Für Sie ist bei dieser Aufgabe gerade nichts zu tun.'),
 ('help.ask.heading', 'de', 'Eine Frage stellen'),
 ('help.ask.placeholder', 'de', 'Zum Beispiel: Warum kann ich diese Rechnung nicht abschließen?'),
 ('help.ask.button', 'de', 'Fragen'),
 ('help.ask.thinking', 'de', 'Einen Moment…'),
 ('help.ask.failed', 'de', 'Leider konnte gerade keine Antwort erstellt werden. Versuchen Sie es erneut oder fragen Sie Ihre AP-Leitung.'),
 ('help.ask.disclaimer', 'de', 'Antworten werden per KI aus dieser Hilfe und den Fakten der geöffneten Aufgabe erzeugt. Prüfen Sie Wichtiges mit Ihrer AP-Leitung.'),
 ('help.screen.dashboard', 'de', 'Ihr Ausgangspunkt. Die Karten fassen die Arbeit zusammen, die auf Sie und Ihr Team wartet, Rechnungen, die Aufmerksamkeit brauchen (nicht zugeordnet, wartet auf das ERP, mögliche Duplikate), und wie die Arbeit durch jede Stufe fließt. Klicken Sie auf eine Karte, um die passende Liste zu öffnen. Mit Anordnen ordnen oder blenden Sie Karten aus.'),
 ('help.screen.tasks', 'de', 'Jede Aufgabe, die Sie sehen können, über alle Stufen. Verfügbare Aufgaben gehören Ihrem Team und warten auf Übernahme, Meine bearbeiten Sie selbst, Gesperrte hat jemand anderes übernommen. Filtern Sie nach Stufe oder suchen Sie, und klicken Sie eine Zeile an, um die Rechnung und ihre Aktionen zu öffnen.'),
 ('help.screen.documents', 'de', 'Jede Rechnung und jedes Dokument im System, ob jemand daran arbeitet oder nicht. Suchen, nach Status filtern und öffnen, um Dokument, Fakten, Verlauf und Chat zu sehen. Hier geöffnete Dokumente sind schreibgeschützt, außer Sie haben eine Aufgabe dazu.'),
 ('help.screen.suppliers', 'de', 'Ihr Lieferantenstamm, aus dem ERP geladen oder hier erfasst. Klicken Sie einen Lieferanten an, um ihn zu sperren, freizugeben, zu aktivieren, zu deaktivieren oder zu bearbeiten. Das ERP ist führend, der nächste Import überschreibt manuelle Änderungen.'),
 ('help.screen.access', 'de', 'Wer was wo darf. Organisationseinheiten definiert Ihre Gesellschaften und Abteilungen, Rollen die Berechtigungen, Personen jeden Benutzer und seine Eigenschaften (einschließlich Genehmigungslimits) und Teams die Gruppen, denen Aufgaben zugewiesen werden.'),
 ('help.screen.sources', 'de', 'Woher Rechnungen kommen: eine E-Mail-Adresse, ein Upload oder UBL. Jede Quelle legt fest, welchen Prozess eine Rechnung startet und welcher Organisation sie zugeordnet wird.'),
 ('help.screen.purchaseorders', 'de', 'Bestellungen, aus dem ERP geladen oder als Peppol-Bestellung empfangen. Rechnungen werden positionsweise dagegen abgeglichen.'),
 ('help.screen.rules', 'de', 'Die Regeln jeder Stufe, in einfacher Sprache geschrieben und in Bedingungen und Aktionen übersetzt. Eine Regel läuft erst, wenn sie bestätigt und aktiviert ist.'),
 ('help.screen.processes', 'de', 'Die Stufen, die eine Rechnung der Reihe nach durchläuft, und welcher Regelsatz in jeder Stufe läuft. Änderungen werden als Entwurf erstellt und als neue Version veröffentlicht, laufende Rechnungen beenden die Version, mit der sie begonnen haben.'),
 ('help.screen.apsetup', 'de', 'Wie Rechnungen abgeglichen, kontiert und genehmigt werden: Abgleichstoleranzen, Kontierungslisten, welche Stufen die Kontierung einschränken, wohin Aufgaben zurückgegeben werden können, und der Genehmigungsmodus mit seinen Definitionen.'),
 ('help.screen.apanalytics', 'de', 'Berichte zu Ihrem AP-Betrieb: Arbeitslast, Lieferantenleistung, finanzielle Leistung, Betrugsprävention, die gesellschaftsübergreifende CFO-Sicht und Talk to an AP Expert.'),
 ('help.screen.viewer', 'de', 'Eine Rechnung und Ihre Aufgabe dazu. Das Dokument ist auf einer Seite, Fakten, Positionen und Kontierung auf der anderen, darunter Verlauf und Chat. Die Schaltflächen oben sind die Aktionen, die Ihnen in dieser Stufe offenstehen. Jede wird unten erklärt, mit dem Grund, warum sie da ist.'),
 ('help.action.claim', 'de', 'Übernehmen Sie diese Aufgabe aus der Warteschlange Ihres Teams, um sie zu bearbeiten. Solange Sie sie halten, kann niemand sonst darauf handeln.'),
 ('help.action.complete', 'de', 'Schließen Sie Ihre Arbeit in dieser Stufe ab. Die Rechnung geht in die nächste Stufe des Prozesses.'),
 ('help.action.route_to_approver', 'de', 'Wählen Sie, wer diese Rechnung genehmigen soll. Die gewählte Person erhält die Genehmigungsaufgabe, und die Rechnung wartet in der Genehmigung, bis sie handelt.'),
 ('help.action.release', 'de', 'Geben Sie diese Aufgabe in die Warteschlange Ihres Teams zurück, damit jemand anderes sie übernehmen kann.'),
 ('help.action.reassign', 'de', 'Übergeben Sie diese Aufgabe direkt an eine namentlich genannte Person im selben Team.'),
 ('help.action.key', 'de', 'Bearbeiten Sie Kopffelder und Positionen der Rechnung und speichern Sie. Nur die Felder, die diese Stufe erlaubt, sind bearbeitbar.'),
 ('help.action.return', 'de', 'Senden Sie die Rechnung mit einem Grund an eine frühere Stufe zurück, die sie bereits durchlaufen hat, damit das Team dort korrigiert.'),
 ('help.action.return_to_supplier', 'de', 'Senden Sie die Rechnung mit Grund und optionalem Kommentar an den Lieferanten zurück. Sie verlässt den Prozess, und der Lieferant erhält eine E-Mail.'),
 ('help.action.discard', 'de', 'Nehmen Sie die Rechnung aus dem Prozess, zum Beispiel ein Duplikat oder ein Dokument, das keine Rechnung ist. Sie wird archiviert, nicht gelöscht.'),
 ('help.reason.task_closed', 'de', 'Diese Aufgabe ist bereits {status}.'),
 ('help.reason.claimed_by_other', 'de', '{name} hat diese Aufgabe übernommen, daher kann nur diese Person darauf handeln. Eine AP-Leitung kann sie freigeben oder neu zuweisen.'),
 ('help.reason.team_task_unclaimed', 'de', 'Diese Aufgabe gehört Ihrem Team und wurde noch nicht übernommen. Übernehmen Sie sie, um die weiteren Aktionen zu sehen.'),
 ('help.reason.lacks_permission', 'de', 'Sie haben {permission} für die Organisation dieser Rechnung nicht, daher können Sie sie ansehen, aber nicht bearbeiten.'),
 ('help.reason.limit_insufficient', 'de', 'Warum An Genehmiger weiterleiten statt Abschließen: Ihr Genehmigungslimit ({currency} {limit}) deckt diese Rechnung ({currency} {amount}) nicht ab, und die Genehmigung steht auf Manuell. Wählen Sie jemanden, der sie genehmigen kann.'),
 ('help.reason.choose_next_approver', 'de', 'Warum An Genehmiger weiterleiten statt Abschließen: Die nächste Stufe, {stage}, nutzt die Genehmigungshierarchie im Modus Manuell, daher wählen Sie, wer diese Rechnung genehmigt.'),
 ('help.reason.limit_covers', 'de', 'Warum Abschließen: Ihr Genehmigungslimit ({currency} {limit}) deckt diese Rechnung ({currency} {amount}) ab, Sie können sie selbst genehmigen.'),
 ('help.reason.complete_moves_on', 'de', 'Abschließen schickt die Rechnung in die nächste Stufe. Die Genehmigungsweiterleitung steht auf {mode}, daher muss hier niemand gewählt werden.'),
 ('help.reason.coding_incomplete', 'de', 'Die Kontierung ist auf {lines} Position(en) nicht abgeschlossen. Jedes Kontierungsfeld, das diese Stufe bearbeiten lässt, braucht auf jeder Position einen gültigen Wert, bevor die Rechnung weitergehen kann.'),
 ('help.reason.return_targets', 'de', 'Sie können diese Rechnung zurückgeben an: {stages}.'),
 ('help.reason.return_no_targets', 'de', 'Zurückgeben ist hier nicht möglich: Keine frühere Stufe, die diese Rechnung durchlaufen hat, ist als Rückgabeziel dieser Stufe eingerichtet (AP-Einrichtung).'),
 ('help.reason.discard_not_here', 'de', 'Verwerfen ist in {stage} nicht erlaubt (AP-Einrichtung, Stufenbeschränkungen).');
